import { expect, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

test("A file of exactly 10 MiB is accepted", { tag: "@DOC-05" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const vendorRes = await member.post("/api/vendors", {
    data: {
      name: uniqueName("DOC-05 Vendor"),
      category: "software",
      contact_email: "billing@doc05-vendor.com",
    },
  });
  expect(vendorRes.status(), await vendorRes.text()).toBe(201);
  const vendor = (await vendorRes.json()) as { id: string; status: string };
  expect(vendor.status, await vendorRes.text()).toBe("draft");

  // Act
  const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "contract",
      file: {
        name: "contract-10mib.txt",
        mimeType: "text/plain",
        buffer: Buffer.alloc(TEN_MIB, "x"),
      },
    },
  });

  // Assert
  expect(res.status(), await res.text()).toBe(201);
  const body = (await res.json()) as { vendor_id: string; kind: string; size_bytes: number };
  expect(body.vendor_id, await res.text()).toBe(vendor.id);
  expect(body.kind, await res.text()).toBe("contract");
  expect(body.size_bytes, await res.text()).toBe(TEN_MIB);
});
